// flm:_entry: the prelude's entry points, which the binding calls through
// this module's namespace. It imports every API module (through `flm:_api`),
// so that every handle class is registered with the reviver before any
// handler runs, and the extension's main module (through its alias
// `flm:_main`). This file is hand-written; the API modules under js/api/ and
// flm:_api are generated by the test `tests/api_surface.rs` from the sources
// under `flm-ext/src/api/`.
import { FlmError, revive, begin_registering, continue_registering, end_registering, registering_now } from "flm:_runtime";
import { FeatureBuilder } from "flm:core/registry";
import "flm:_api";
import * as MAIN from "flm:_main";

// The namespace of the main module, for the binding's tests.
export { MAIN };

// The extension's stem and the path of its main module, set by `define`.
let STEM = "";
let MAIN_PATH = "";

// Whether the default export finished: set by a callback on its answer,
// which the queued jobs run.
let FINISHED = false;

// Whether `packages` read the package objects: `ext.package` is refused
// afterwards (a handler may reach an `ext` the default export kept).
let READ = false;

// The package objects `ext.package` recorded: package name → object.
const PACKAGES = new Map();

// The reports of the package objects, one per `ext.package` call, in call
// order: what `packages` answers.
const REPORTS = [];

// The objects each feature's `register` declared on this engine instance:
// `${package}\u0000${feature}` → { stages: name → object, hooks: element →
// object, lowers: rule → object, rewrites: stage name → object, providers:
// name → object, templates: name → object, aspects: element → {
// Referenceable, Sectioning }, late_inits: [object], finalizers: [object] }.
const REGISTRY = new Map();

// Restarts the sandbox's random sequence: every handler call starts alike.
function begin_call() {
  if (typeof globalThis.__flm_begin_call === "function") globalThis.__flm_begin_call();
}

// A refusal of `ext.package`'s arguments.
function refuse(detail) {
  throw new FlmError({ kind: "argument", method: "package", detail });
}

// Whether `value` is a plain object (not null, not a list).
function is_object(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Whether `value` is absent (undefined or null).
function absent(value) {
  return value === undefined || value === null;
}

// Whether `value` is a list of texts.
function texts(value) {
  return Array.isArray(value) && value.every(item => typeof item === "string");
}

// Whether `value` is something JSON drops or cannot write: a function, a
// symbol or a BigInt.
function not_data(value) {
  return typeof value === "function" || typeof value === "symbol" || typeof value === "bigint";
}

// The key path of the first value inside `value` (at `path`, empty for the
// feature object itself) that JSON would drop or change without a word,
// with the text of its refusal's subject; `null` when there is none.
// `open` holds the objects being walked: a value among them closes a cycle,
// answered as `{ cycle }`, the key path where it closes.
function find_not_data(value, path, open) {
  if (not_data(value)) return { subject: `\`${path}\`` };
  if (value === null || typeof value !== "object") return null;
  if (open.has(value)) return { cycle: `\`${path}\`` };
  open.add(value);
  try {
    const symbols = Object.getOwnPropertySymbols(value);
    if (symbols.length > 0) {
      const of = path === "" ? "" : ` of \`${path}\``;
      return { key: `the key \`${String(symbols[0])}\`${of}` };
    }
    const entries = Array.isArray(value)
      ? Array.from(value, (item, index) => [`[${index}]`, item])
      : Object.entries(value).map(([key, item]) => [path === "" ? key : `.${key}`, item]);
    for (const [step, item] of entries) {
      const found = find_not_data(item, `${path}${step}`, open);
      if (found) return found;
    }
    return null;
  } finally {
    open.delete(value);
  }
}

// define(stem, main): calls the main module's default export once with the
// extension builder `ext`. Its packages are read by `packages`, once the
// binding has run the queued jobs (an `async` default export declares them
// all); its answer must have settled by then.
export function define(stem, main) {
  STEM = stem;
  MAIN_PATH = main;
  FINISHED = false;
  READ = false;
  if (typeof MAIN.default !== "function") {
    throw new FlmError({
      kind: "main",
      detail: `the main module \`${main}\` of the extension \`${stem}\` must have a function as its default export (\`export default function (ext) { … }\`)`,
    });
  }
  PACKAGES.clear();
  REPORTS.length = 0;
  // The extension builder: its one method declares a package. A later
  // extension point is a method added here, never a new export.
  const ext = Object.freeze({
    package(name, object) {
      if (READ)
        refuse(`the extension \`${stem}\` must call \`ext.package\` while the default export of its main module \`${main}\` runs, before its packages are read`);
      if (typeof name !== "string" || name === "")
        refuse(`the extension \`${stem}\` calls \`ext.package\` with a package name that is not a non-empty text`);
      const where = `of the package \`${name}\` of the extension \`${stem}\``;
      if (!is_object(object)) refuse(`the package \`${name}\` of the extension \`${stem}\` must be an object`);
      if (!absent(object.uses) && !texts(object.uses)) refuse(`\`uses\` ${where} must be a list of texts`);
      if (!absent(object.templates) && !texts(object.templates)) refuse(`\`templates\` ${where} must be a list of texts`);
      if (!absent(object.host) && !texts(object.host)) refuse(`\`host\` ${where} must be a list of texts`);
      if (!absent(object.flm) && !is_object(object.flm)) refuse(`\`flm\` ${where} must be a map`);
      if (!absent(object.features) && !is_object(object.features))
        refuse(`\`features\` ${where} must be a map from a feature's name to its object`);
      const features = [];
      for (const [feature, value] of Object.entries(object.features ?? {})) {
        if (!is_object(value) || typeof value.register !== "function")
          refuse(`the feature \`${feature}\` ${where} must be an object with a \`register\` function`);
        const { register, ...rest } = value;
        // The feature object itself is open: `f.self = f` closes a cycle at `self` (A62).
        const found = find_not_data(rest, "", new Set([value]));
        if (found?.subject)
          refuse(`${found.subject} of the feature \`${feature}\` ${where} must be a text, a number, a boolean, a list or a map; the one function of a feature object is \`register\``);
        if (found?.key)
          refuse(`${found.key} of the feature \`${feature}\` ${where} must be a text`);
        if (found?.cycle)
          refuse(`${found.cycle} of the feature \`${feature}\` ${where} must not contain itself`);
        features.push({ name: feature, object: rest });
      }
      if (!PACKAGES.has(name)) PACKAGES.set(name, object);
      REPORTS.push({
        name,
        uses: object.uses ?? null,
        flm: object.flm ?? null,
        templates: object.templates ?? null,
        host: object.host ?? null,
        features,
      });
    },
  });
  // Its answer, a promise or any value, settles in the queued jobs the
  // binding runs next; a rejection stays without a handler (the callback
  // takes the fulfillment only), so the binding reports it.
  Promise.resolve(MAIN.default(ext)).then(() => { FINISHED = true; });
}

// packages(): refused unless the default export finished; else the JSON
// text of the package objects `ext.package` recorded, one item per call,
// in call order (each feature as `{ name, object }`, its object without
// its `register`, the features as a list in the order written).
export function packages() {
  READ = true;
  if (!FINISHED) {
    throw new FlmError({
      kind: "main",
      detail: `the default export of the main module \`${MAIN_PATH}\` of the extension \`${STEM}\` must finish while the extension loads; its promise is still pending after its queued jobs ran`,
    });
  }
  return JSON.stringify(REPORTS);
}

// The feature `feature` of the package `pkg`.
function find_feature(pkg, feature) {
  const features = PACKAGES.get(pkg)?.features;
  const found = features && Object.prototype.hasOwnProperty.call(features, feature) ? features[feature] : undefined;
  if (!found) {
    throw new FlmError({ kind: "handler", detail: `the package \`${pkg}\` of the extension \`${STEM}\` must have a feature \`${feature}\`` });
  }
  return found;
}

// Runs the feature's `register(b, settings)` with `builder`, recording its
// stage and hook objects; `rehearsal` when the builder dispatches nothing.
function register_with(pkg, feature, settings, builder, rehearsal) {
  begin_call();
  const b = new FeatureBuilder(builder);
  begin_registering(STEM, pkg, feature, rehearsal);
  let done = null;
  try {
    find_feature(pkg, feature).register(b, settings);
  } finally {
    done = end_registering();
  }
  REGISTRY.set(`${pkg}\u0000${feature}`, done);
}

// register(pkg, feature, settingsJson, builderJson): the feature's
// `register(b, settings)`.
export function register(pkg, feature, settings, builder) {
  register_with(pkg, feature, JSON.parse(settings), JSON.parse(builder)["@handle"], false);
}

// The rehearsal: the feature's `register` again, with the configuration of
// the real registration and a builder whose token is `null`, then each
// finalizer it registered with such a builder (those `register` recorded: a
// finalizer a finalizer registers is not replayed), so that this engine
// instance holds the objects the feature declared.
export function rehearse(pkg, feature, settings) {
  register_with(pkg, feature, JSON.parse(settings), null, true);
  const done = REGISTRY.get(`${pkg}\u0000${feature}`);
  const count = done.finalizers.length;
  for (let index = 0; index < count; index++) {
    finalize_with(done, index, new FeatureBuilder(null), true);
  }
}

// run_stage(pkg, feature, name, cxJson, outJson): the stage's `run(cx, out)`.
export function run_stage(pkg, feature, name, cx, out) {
  begin_call();
  const stage = REGISTRY.get(`${pkg}\u0000${feature}`)?.stages.get(name);
  if (!stage) {
    throw new FlmError({ kind: "handler", detail: `the stage \`${name}\` must be declared by \`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\`` });
  }
  stage.run(revive(JSON.parse(cx)), revive(JSON.parse(out)));
}

// expand(pkg, feature, element, nodeJson, cxJson, xpJson): the hook's
// `expand(node, cx, xp)`, its answer as JSON text.
export function expand(pkg, feature, element, node, cx, xp) {
  begin_call();
  const hook = REGISTRY.get(`${pkg}\u0000${feature}`)?.hooks.get(element);
  if (!hook) {
    throw new FlmError({ kind: "handler", detail: `the expansion hook of the element \`${element}\` must be attached by \`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\`` });
  }
  const answer = hook.expand(revive(JSON.parse(node)), revive(JSON.parse(cx)), revive(JSON.parse(xp)));
  return JSON.stringify(answer ?? null);
}

// lower(pkg, feature, rule, nodeJson, cxJson, lwJson): the body's
// `lower(node, cx, lw)` of the lowering rule `rule`, its answer as JSON text.
export function lower(pkg, feature, rule, node, cx, lw) {
  begin_call();
  const body = REGISTRY.get(`${pkg}\u0000${feature}`)?.lowers.get(rule);
  if (!body) {
    throw new FlmError({ kind: "handler", detail: `the lowering rule \`${rule}\` must be built by \`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\`` });
  }
  const answer = body.lower(revive(JSON.parse(node)), revive(JSON.parse(cx)), revive(JSON.parse(lw)));
  return JSON.stringify(answer ?? null);
}

// restage(pkg, feature, name, nodeJson, cxJson, rsJson): the rewrite stage
// `name`'s `restage(node, cx, rs)` for one node, its answer (a `Restage`) as
// JSON text.
export function restage(pkg, feature, name, node, cx, rs) {
  begin_call();
  const stage = REGISTRY.get(`${pkg}\u0000${feature}`)?.rewrites.get(name);
  if (!stage) {
    throw new FlmError({ kind: "handler", detail: `the rewrite stage \`${name}\` must be declared by \`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\`` });
  }
  const answer = stage.restage(revive(JSON.parse(node)), revive(JSON.parse(cx)), revive(JSON.parse(rs)));
  return JSON.stringify(answer ?? null);
}

// The handler object `name` of the kind `kind` ("providers", "templates")
// that the feature `feature` of the package `pkg` contributed: from the
// `register` of that feature running now (a template module's `describe`
// runs inside it), else from what its last `register` on this instance
// recorded. `what` names it in the refusal (D8).
function contributed_object(pkg, feature, kind, name, what) {
  const live = registering_now();
  const recorded = live !== null && live.pkg === pkg && live.feature === feature
    ? live[kind]
    : REGISTRY.get(`${pkg}\u0000${feature}`)?.[kind];
  const found = recorded?.get(name);
  if (!found) {
    throw new FlmError({ kind: "handler", detail: `${what} must be contributed by \`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\`` });
  }
  return found;
}

// answer_all(pkg, feature, name, requestsJson, cxJson): the citation
// provider's answers to the requests, as JSON text. The provider's
// `answer_all(requests, cx)` when it has one, else its `answer(request, cx)`
// once per request in order: the default of `CitationProvider::answer_all`,
// the one computation of the prelude beyond forwarding.
export function answer_all(pkg, feature, name, requests, cx) {
  begin_call();
  const provider = contributed_object(pkg, feature, "providers", name, `the citation provider \`${name}\``);
  const list = JSON.parse(requests);
  const context = revive(JSON.parse(cx));
  const answer = typeof provider.answer_all === "function"
    ? provider.answer_all(list, context)
    : list.map(request => provider.answer(request, context));
  return JSON.stringify(answer ?? null);
}

// template_describe(pkg, feature, name, settingsJson): the template
// module's `describe(settings)`, as JSON text. It runs inside the
// `register` that contributes the module, so the sandbox's random sequence
// is not restarted (the `register` it interrupts continues it).
export function template_describe(pkg, feature, name, settings) {
  const template = contributed_object(pkg, feature, "templates", name, `the template module \`${name}\``);
  return JSON.stringify(template.describe(JSON.parse(settings)) ?? null);
}

// template_files(pkg, feature, name, dataJson, cxJson): the template
// module's `files(data, cx)`, as JSON text; none when it has no `files`.
export function template_files(pkg, feature, name, data, cx) {
  begin_call();
  const template = contributed_object(pkg, feature, "templates", name, `the template module \`${name}\``);
  if (typeof template.files !== "function") return "[]";
  return JSON.stringify(template.files(JSON.parse(data), revive(JSON.parse(cx))) ?? null);
}

// template_render(pkg, feature, name, dataJson, cxJson): the template
// module's `render(data, cx)`, as JSON text.
export function template_render(pkg, feature, name, data, cx) {
  begin_call();
  const template = contributed_object(pkg, feature, "templates", name, `the template module \`${name}\``);
  return JSON.stringify(template.render(JSON.parse(data), revive(JSON.parse(cx))) ?? null);
}

// The `register` of the feature `feature` of the package `pkg`, as the
// messages of the entries below name it.
function owner(pkg, feature) {
  return `\`register\` of the feature \`${feature}\` of the package \`${pkg}\` of the extension \`${STEM}\``;
}

// The handler object of the aspect `kind` of the element `element`, or a
// thrown refusal whose text begins with `what`.
function aspect_object(pkg, feature, kind, element, what) {
  const object = REGISTRY.get(`${pkg}\u0000${feature}`)?.aspects.get(element)?.[kind];
  if (!object) {
    throw new FlmError({ kind: "handler", detail: `${what} of the element \`${element}\` must be answered by an aspect attached by ${owner(pkg, feature)}` });
  }
  return object;
}

// points(pkg, feature, element, nodeJson): the `points(node)` of the
// element's `Referenceable`, its answer as JSON text.
export function points(pkg, feature, element, node) {
  begin_call();
  const object = aspect_object(pkg, feature, "Referenceable", element, "the reference points");
  return JSON.stringify(object.points(revive(JSON.parse(node))) ?? null);
}

// One method of the element's `Sectioning`, its answer as JSON text.
function sectioning(pkg, feature, element, node, method) {
  begin_call();
  const object = aspect_object(pkg, feature, "Sectioning", element, "the sectioning");
  return JSON.stringify(object[method](revive(JSON.parse(node))) ?? null);
}

// level(pkg, feature, element, nodeJson): the `level(node)` of the
// element's `Sectioning`.
export function level(pkg, feature, element, node) { return sectioning(pkg, feature, element, node, "level"); }

// in_toc(pkg, feature, element, nodeJson): its `in_toc(node)` (called only
// when the object has it).
export function in_toc(pkg, feature, element, node) { return sectioning(pkg, feature, element, node, "in_toc"); }

// toc_title(pkg, feature, element, nodeJson): its `toc_title(node)` (called
// only when the object has it).
export function toc_title(pkg, feature, element, node) { return sectioning(pkg, feature, element, node, "toc_title"); }

// late_init(pkg, feature, index, langJson, diagsJson): the
// `late_init(lang, diags)` of the feature's late-initialization hook at the
// position `index`.
export function late_init(pkg, feature, index, lang, diags) {
  begin_call();
  const hook = REGISTRY.get(`${pkg}\u0000${feature}`)?.late_inits[Number(index)];
  if (!hook) {
    throw new FlmError({ kind: "handler", detail: `the late-initialization hook ${index} must be registered by ${owner(pkg, feature)}` });
  }
  hook.late_init(revive(JSON.parse(lang)), revive(JSON.parse(diags)));
}

// Runs the finalizer at the position `index` of what `done` recorded with
// `builder`, recording what it declares into `done`.
function finalize_with(done, index, builder, rehearsal) {
  continue_registering(done, rehearsal);
  try {
    done.finalizers[index].finalize(builder);
  } finally {
    end_registering();
  }
}

// finalize(pkg, feature, index, builderJson): the `finalize(b)` of the
// feature's finalizer at the position `index`, with the builder of the
// build's second round; what it declares is recorded with what the feature's
// `register` declared.
export function finalize(pkg, feature, index, builder) {
  begin_call();
  const done = REGISTRY.get(`${pkg}\u0000${feature}`);
  if (!done?.finalizers[Number(index)]) {
    throw new FlmError({ kind: "handler", detail: `the finalizer ${index} must be registered by ${owner(pkg, feature)}` });
  }
  finalize_with(done, Number(index), revive(JSON.parse(builder)), false);
}
